    nav_devices: "الأجهزة المختبَرة",
    about_devices_link: "على أي أجهزة قراءة إلكترونية اختُبرت PaperGames - وكيف تتحقق من جهازك",
    devices_intro: "تعمل PaperGames في متصفح الويب الخاص بجهاز القراءة الإلكتروني. أما الأجهزة التي تعمل عليها فعلًا فلا تُعرف إلا حيث جرّبها أحد وأبلغ عن ذلك. تسرد هذه الصفحة تلك الأجهزة، وتوضح بالقدر نفسه ما لم يُختبر.",
    devices_list_title: "أجهزة وردت عنها تقارير",
