    devices_checked_user_report: "اللعب في المتصفح المدمج في الجهاز؛ وأُبلغ عن المشكلات التي وُجدت",
    devices_checked_dev_device: "جهاز التطوير: يُفحص عليه كل تغيير",
    devices_screen_unknown: "لم يُذكر الطراز",
    devices_untested: "جميع الأجهزة الأخرى غير مختبَرة. قد تعمل PaperGames عليها جيدًا، لكن لم يُبلغ أحد بعد.",
    devices_requirements: "تحتاج PaperGames إلى متصفح حديث يدعم JavaScript وفق ES2015 (const والدوال السهمية وPromise) وfetch وFlexbox ومتغيرات CSS، إضافةً إلى Service Worker للعب دون اتصال. وبحسب ما هو معروف، لا يستطيع ذلك متصفح Kindle القديم ولا متصفح Kobo المبني على Qt WebKit 538؛ وتعرض PaperGames عليهما رسالة قصيرة فقط.",
    devices_check_title: "تحقق منها على جهازك",
    devices_step1_title: "1. افتح الصفحة",
    devices_step1_text: "افتح PaperGames في المتصفح المدمج في جهاز القراءة لديك. انتبه إلى: أن الصفحة تُحمَّل، وأن النص واضح، وأن لا شيء مقطوع عند الحافة.",
    devices_step2_title: "2. ابدأ لعبة",
    devices_step2_text: "ابدأ لعبة، مثل سودوكو أو الشطرنج، وقم ببضع حركات. انتبه إلى: أن كل لمسة تصيب المربع الذي قصدته، وأن اللوحة تتسع في الشاشة دون تمرير جانبي.",
    devices_step3_title: "3. افتح الإعدادات",
    devices_step3_text: "افتح الإعدادات وغيّر حجم النص والتباين العالي. انتبه إلى: أن الصفحة تتغير فورًا وأن كل شيء يبقى مقروءًا.",
    devices_step4_title: "4. انتقل إلى وضع عدم الاتصال",
    devices_step4_text: "انتظر حتى تُظهر الصفحة الرئيسية أن PaperGames جاهزة للعمل دون اتصال، ثم أوقف الواي فاي وأعد تحميل الصفحة. انتبه إلى: أن الصفحة واللعبة ما زالتا تُفتحان.",
    devices_step5_title: "5. عُد لاحقًا",
    devices_step5_text: "اترك لعبة في منتصفها، وأغلق المتصفح ثم افتحه مجددًا لاحقًا. انتبه إلى: أن اللعبة في المكان نفسه الذي تركتها فيه تمامًا.",
