    history_title: "مكتبة تاريخ الألعاب",
    history_intro: "لكل لعبة في هذه المجموعة قصتها الخاصة - بعضها يزيد عمره على خمسة آلاف عام، وبعضها بالكاد عقد من الزمن. اقرأها هنا بالترتيب التقريبي لظهور كل لعبة، أو انتقل مباشرة إلى صفحة التاريخ الكاملة لأي منها.",
    history_dates_note: "تواريخ أقدم الألعاب تقريبية - فأصولها الدقيقة كثيرًا ما ضاعت في التاريخ أو ما زال المؤرخون يختلفون فيها.",
