    home_history_desc: "اقرأ قصة أصل كل لعبة، من مصر القديمة حتى العقد الماضي - تاريخ فقط، بلا تصفح.",
    home_chess_desc: "اللعبة الكلاسيكية. لاعبان على الجهاز نفسه، أو ضد المحرك المدمج، أو عبر الإنترنت على Lichess.",
    home_go_desc: "لعبة الأراضي العريقة. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، بثلاثة أحجام للرقعة وثلاثة مستويات صعوبة.",
    home_checkers_desc: "لعبة القفز والأسر الكلاسيكية. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، بثلاثة مستويات صعوبة.",
    home_ur_desc: "لعبة سباق عمرها 4600 عام أُعيد اكتشافها من بلاد الرافدين القديمة. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، مع خانات الوردة والأسر بالهبوط.",
    home_morris_desc: "لعبة استراتيجية عمرها قرون لوضع القطع وتحريكها لتكوين طواحين. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، مع قاعدة الطيران الكلاسيكية في نهاية اللعبة.",
    home_backgammon_desc: "لعبة سباق النرد الكلاسيكية. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، مع الحاجز وإخراج القطع وضرب القطع المنفردة.",
    home_xiangqi_desc: "الشطرنج الصيني: قادة وفيلة ومدافع وغيرها على شبكة 9×10. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، مع إمكانية التبديل بين الحروف الصينية والرموز الغربية.",
    home_mancala_desc: "من أقدم عائلات الألعاب في العالم: وزّع البذور حول الرقعة لتملأ مخزنك. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، مع الأسر والأدوار الإضافية.",
    home_reversi_desc: "اقلب لون الرقعة بمحاصرة أقراص خصمك. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
