    chess_history_intro: "من لعبة حرب هندية قديمة إلى أكثر ألعاب الطاولة دراسةً في العالم - عبر الشطرنج القارات والقرون ليصبح ما هو عليه اليوم.",
    go_history_intro: "غو من أقدم ألعاب الطاولة التي ما زالت تُلعب بشكلها الأصلي - لعبة أراضٍ وأحجار تمتد جذورها على الأرجح إلى أكثر من 2500 عام في الصين.",
    checkers_history_intro: "الداما لعبة قواعدها بسيطة واستراتيجيتها عميقة، وُلدت من الجمع بين رقعة قديمة وطريقة أحدث في الأسر.",
    ur_history_intro: "بعمر يقارب 4600 عام، تُعد لعبة أور الملكية من أقدم ألعاب الطاولة المكتشفة على الإطلاق - وبفضل عمل تحقيقي امتد ألفي عام، من الألعاب القديمة القليلة التي ما زلنا نستطيع لعبها بقواعد أُعيد بناؤها من مصدر مكتوب قديم.",
    morris_history_intro: "قليلة هي الألعاب التي نُقشت على هذا العدد من الأسطح عبر هذا العدد من القرون مثل لعبة المربعات التسعة - من أسطح المعابد المصرية إلى أروقة الكاتدرائيات الإنجليزية.",
    backgammon_history_intro: "تمتد شجرة عائلة الطاولة عبر كل حضارة تقريبًا رمت النرد - من بلاد الرافدين وروما القديمتين إلى مقاهي الشرق الأوسط الحديث.",
    xiangqi_history_intro: "يشترك الشطرنج الصيني مع الشطرنج الدولي في جذور عميقة، لكنه سلك طريقه المميز على مدى أكثر من ألف عام ليصبح اللعبة التي يلعبها مئات الملايين اليوم.",
    mancala_history_intro: "المنقلة ليست لعبة واحدة بل عائلة كاملة من الألعاب - من أقدم عائلات الألعاب على الأرض، مبنية حول الفعل البسيط والعالمي لنقل البذور أو الحصى بين الحفر.",
    reversi_history_intro: "لعبة صالونات فيكتورية عادت بعد قرن تقريبًا في اليابان باسم جديد وبوضع بداية ثابت.",
    fourinarow_history_intro: "فكرة بسيطة تعمل بالجاذبية تحولت إلى لعبة كلاسيكية في أنحاء العالم.",
    gomoku_history_intro: "لعبة بسيطة لصفّ الأحجار أجبرت بساطتها نفسها اللاعبين المتنافسين على تغيير قواعدها.",
    tictactoe_history_intro: "ربما أشهر ألعاب الورقة والقلم على الإطلاق – بجذور في روما القديمة ومكان في تاريخ الحواسيب.",
    senet_history_intro: "من أقدم ألعاب الطاولة المكتشفة على الإطلاق - ومن الألعاب التي ضاعت قواعدها الدقيقة منذ آلاف السنين.",
    shogi_history_intro: "نسخة اليابان من عائلة الشطرنج، والمتغير الرئيسي الوحيد الذي لا تغادر فيه القطعة المأسورة اللعبة - بل تنضم إلى الطرف الذي أسرها.",
    sudoku_history_intro: "خلافًا لكل لعبة أخرى في هذه المجموعة، ليس لسودوكو أي نسب قديم على الإطلاق - فاللغز بشكله الحديث لا يعود إلا إلى عام 1979.",
    pegsolitaire_history_intro: "لغز للاعب واحد قديم بما يكفي لأن تكون له أسطورته الخاصة عن أصله، وموضوع إحدى أكثر النتائج إثارة للدهشة في الرياضيات الترفيهية.",
    minesweeper_history_intro: "لغز لم تصبح قاعدته المميزة - نقلة أولى آمنة تمامًا - معيارًا إلا حين صارت الحواسيب، لا الصفحات المطبوعة، قادرة على توليد رقعة جديدة عند الطلب.",
    nonogram_history_intro: "لغز منطقي اختُرع مرتين في اليابان في الوقت نفسه تقريبًا، كلٌّ على حدة - وسُمّي باسم أحد مخترعَيه.",
    twenty48_history_intro: "لعبة مبنية بالكامل تقريبًا من أفكار ألعاب أخرى، صُنعت في عطلة نهاية أسبوع، وقلّدها أناس أكثر مما قلّدوا ربما أي لعبة متصفح قبلها.",
    mahjong_history_intro: "لعبة مطابقة بلاطات للاعب واحد، سُمّيت على اسم لعبة مختلفة تمامًا لأربعة لاعبين واستعارت شكلها، ولا تشترك معها في شيء آخر تقريبًا.",
    back_home: "→ العودة إلى الرئيسية",
