    connect_lichess: "اتصل (Lichess)",
    chess_lichess_note: "اختياري: يحتاج وضع الاتصال إلى الإنترنت وحساب Lichess. اللعب ضد الكمبيوتر يعمل دون اتصال كالمعتاد.",
    logout: "تسجيل الخروج",
    find_game: "ابحث عن مباراة",
    load_game: "حمّل المباراة",
    guide_title: "الدليل: PaperGames على جهازك",
    guide_intro: "ثلاث طرق لنقل PaperGames إلى جهاز قراءة إلكتروني، من الأسهل إلى الأكثر يدوية تقريبًا.",
    guide_web_title: "1. افتحها ببساطة في المتصفح",
    guide_web_body: "لا يوجد شيء لتنزيله ولا شيء لتثبيته. افتح عنوان الويب نفسه في متصفح جهاز القراءة واحفظه في المفضلة. بعد الزيارة الأولى تخزّن PaperGames نفسها تلقائيًا للاستخدام دون اتصال - أوقف الواي فاي وستواصل العمل. قد يستغرق الحفظ دقيقة أو دقيقتين؛ اترك الصفحة مفتوحة حتى ذلك الحين. تعرض الصفحة الرئيسية متى اكتمل ذلك (\"جاهز للعمل دون اتصال\"). الاستثناء الوحيد هو وضع Lichess عبر الإنترنت في الشطرنج، إذ يحتاج إلى اتصال فعلي؛ أما بقية الألعاب هنا فتعمل دون اتصال ولا تتأثر.",
    guide_pwa_title: "2. أضفها إلى الشاشة الرئيسية",
    guide_pwa_body: "إذا كان متصفح جهاز القراءة يقدّم خيار «إضافة إلى الشاشة الرئيسية» أو «تثبيت التطبيق»، فاستخدمه. عندها تُفتح PaperGames كتطبيق عادي بملء الشاشة، دون إطار المتصفح.",
    guide_sideload_title: "3. النقل عبر USB",
    guide_sideload_body: "انسخ جميع ملفات التطبيق إلى الجهاز عبر USB وافتح index.html مباشرة من الذاكرة المحلية (عنوان file://). اللعب دون اتصال يعمل بالطريقة نفسها تمامًا. الشيء الوحيد الذي لا يعمل عبر file:// هو تسجيل الدخول إلى Lichess (إذ يتطلب OAuth عنوان http/https حقيقيًا) - أما وضع اللاعبَين ووضع اللعب ضد الكمبيوتر فلا يتأثران في أي لعبة هنا.",
    guide_offline_title: "ما الذي يعمل دون اتصال",
    guide_offline_body: "كل شيء باستثناء مباريات Lichess عبر الإنترنت في الشطرنج: وضع اللاعبَين والخصم الحاسوبي المدمج بجميع مستوياته، في كل لعبة هنا، يعملان بالكامل على الجهاز دون أي خادم.",
    guide_update_title: "لا ترى أحدث إصدار؟",
    guide_update_body: "تخزّن PaperGames نفسها لتواصل العمل دون اتصال، وقد يعني ذلك في بعض متصفحات أجهزة القراءة أن التحديث يتأخر في الظهور حتى بعد إعادة التحميل. يمسح هذا الزر ذلك التخزين ويفرض نسخة جديدة من كل ملف - ستحتاج إلى اتصال بالإنترنت لكي يعمل.",
    guide_update_button: "فرض التحديث الآن",
    guide_update_done: "تم مسح التخزين. جارٍ إعادة التحميل…",
    about_intro: "بحثت عن لعبة شطرنج بسيطة لجهاز القراءة الإلكتروني، لكنني لم أجد سوى أناس يبحثون مثلي، لا يلعبون. فصنعت لعبتي بنفسي. هكذا وُلدت PaperGames، ويسعدني أن أشاركها مع الجميع. وقد نمت منذ ذلك الحين لتصبح مجموعة صغيرة من ألعاب الطاولة المناسبة للحبر الإلكتروني، مع المزيد في الطريق.",
    about_donate_intro: "إذا أعجبتك PaperGames أو كانت لديك أفكار للتحسين، يمكنك إرسال ملاحظاتك ودعم المشروع هنا:",
    about_donate_button: "اشترِ لي قهوة",
    about_qr_text: "أو امسح رمز QR هذا لفتح صفحة التبرع على هاتفك:",
    about_credits: "قطع الشطرنج («cburnett») من رسم Colin M.L. Burnett، مستخدمة بموجب رخصة BSD (ثلاثة بنود؛ النص الكامل في الملف NOTICE). قطع شيانغتشي الرمزية: رسوم أصلية من Inductiveload، عدّلها Kadagaden قطعةً قطعة (github.com/Kadagaden/chess-pieces)، بموجب CC BY-SA 4.0: https://creativecommons.org/licenses/by-sa/4.0/ رموز كانجي لقطع الشوغي: معدّلة من مجموعة «kanji_light» من Kadagaden (github.com/Kadagaden/shogi-pieces)، بموجب CC BY 4.0: https://creativecommons.org/licenses/by/4.0/ أيقونتا كاسحة الألغام وFreeCell في الصفحة الرئيسية من Skoll وAussiesim، من game-icons.net (CC BY 3.0).",
    about_license: "يخضع هذا الموقع وشيفرته المصدرية لرخصة PolyForm Noncommercial License 1.0.0 (نص الرخصة في الملف LICENSE). أما الأجزاء من مؤلفين آخرين، مثل مجموعات القطع والأيقونات، فتبقى بتراخيصها الخاصة، وهي مذكورة في الملف NOTICE.",
    about_lichess_disclaimer: "تعمل ميزة الشطرنج عبر الإنترنت في PaperGames عبر واجهة lichess.org البرمجية العامة. PaperGames مشروع مستقل، وليس تابعًا لـ Lichess ولا معتمدًا أو مراجَعًا منها.",
    about_trademarks: "تذكر صفحات التاريخ أسماء ألعاب تجارية لتوضيح أصل مبدأ اللعب بموضوعية. وبعض هذه الأسماء علامات تجارية مسجلة لمالكيها. ولا تربط PaperGames أي صلة بهؤلاء المالكين، ولا تحظى بتأييدهم أو رعايتهم أو مراجعتهم. وكل الألعاب هنا تطبيقات مستقلة؛ ولا تُستخدم أي مواد من الإصدارات التجارية.",
    nikoli_trademark_heading: "ملاحظة عن الأسماء",
    nikoli_trademark_notice: "الأسماء 数独 (سودوكو) وカックロ (كاكورو) وスリザーリンク (سليذرلينك) علامات تجارية مسجلة في اليابان لدار النشر Nikoli، و橋をかけろ (هاشيووكاكيرو) هو الاسم الذي تنشر به Nikoli هذا اللغز. ولا تربط PaperGames أي صلة بـ Nikoli، ولا تحظى بدعمها أو مراجعتها، ولذلك تستخدم أسماء أخرى في النسخة اليابانية. أما أنواع الألغاز نفسها فحرة؛ وكل لغز هنا يُنشأ من جديد على الجهاز.",
    impressum_trademarks_heading: "العلامات التجارية",
    impressum_trademarks_body: "تذكر صفحات التاريخ أسماء ألعاب تجارية لتوضيح أصل مبدأ اللعب بموضوعية. وبعض هذه الأسماء علامات تجارية مسجلة لمالكيها. ولا تربط PaperGames أي صلة بهؤلاء المالكين، ولا تحظى بتأييدهم أو رعايتهم أو مراجعتهم. وكل الألعاب هنا تطبيقات مستقلة؛ ولا تُستخدم أي مواد من الإصدارات التجارية.",
    about_back: "→ العودة إلى الرقعة",
