    game_pairs: "أزواج",
    home_pairs_desc: "اقلب بطاقتين وابحث عن الأزواج: لعبة مطابقة البطاقات الكلاسيكية بأشكال أو حيوانات أو فواكه وخضروات أو مركبات بسيطة بالأبيض والأسود. وحدك في مواجهة عدد النقلات، أو لاعبان على الجهاز نفسه، أو ضد المحرك المدمج.",
    game_futoshiki: "فوتوشيكي",
    home_futoshiki_desc: "املأ الشبكة بحيث يحتوي كل صف وكل عمود على كل رقم مرة واحدة، وتشير كل علامة بين خانتين إلى الرقم الأصغر. أحجام من 4x4 إلى 6x6، تُولَّد من جديد بحل وحيد.",
