    game_foxandgeese: "الثعلب والإوز",
    home_foxandgeese_desc: "لعبة الصيد القروسطية على الصليب ذي النقاط الـ33: ثعلب واحد ضد 13 إوزة. العب بأي من الجانبين، محليًا بين لاعبين أو ضد المحرك المدمج.",
    foxandgeese_board_label: "لوحة الثعلب والإوز",
