    game_seega: "السيجة",
    home_seega_desc: "لعبة مصرية للرص والحصار على لوحة 5x5: يضع الجانبان أولًا أحجارهما الاثني عشر، ثم يكون الأسر بالحصر. محليًا بين لاعبين أو ضد المحرك المدمج.",
    seega_board_label: "لوحة السيجة",
