    game_romme: "الرمي (Rommé)",
    home_romme_desc: "الرمي الألماني بمجموعتين من الورق وست ورقات جوكر: أنزل مجموعات وسلاسل، وأضف إلى أي تركيبة على الطاولة، وتخلص من كل أوراقك. من 2 إلى 4 لاعبين، ضد الحاسوب أو على جهاز واحد.",
    romme_history_intro: "الرمي كما يُلعب في ألمانيا بمجموعتين من الورق مع الجوكر، وهو واحد من ألعاب كثيرة تُجمع فيها المجموعات والسلاسل.",
