    seo_t_game: "{s} على شاشات الحبر الإلكتروني – العب دون اتصال وبلا إعلانات",
    seo_title_index: "PaperGames – {games} لعبة مجانية لقارئات الحبر الإلكتروني",
    seo_desc_index: "{games} لعبة مجانية لقارئات الحبر الإلكتروني المزودة بمتصفح، جُرّبت على Tolino وBoox وPocketBook: الشطرنج والسودوكو وغو وغيرها. دون اتصال، بلا إعلانات، بـ12 لغة.",
    seo_title_about: "عن PaperGames – {games} لعبة لوحية مجانية للحبر الإلكتروني",
    seo_desc_about: "لماذا وُجد PaperGames وكيف بُني وكيف تدعم المشروع. مجموعة مجانية دون اتصال وبلا إعلانات من {games} لعبة لوحية وألغازًا كلاسيكية.",
    nav_calm: "اللعب بهدوء",
    about_calm_link: "اللعب بهدوء: بلا رسوم متحركة، بلا أصوات، بلا إعلانات",
    calm_intro: "صُمّم PaperGames للعب بهدوء. وهذا يعني:",
    calm_point_1: "لا رسوم متحركة: لا شيء يومض أو ينزلق أو يقفز. كل تغيير يظهر دفعة واحدة.",
    calm_point_2: "لا أصوات.",
    calm_point_3: "لا إعلانات ولا إشعارات. لا تحتاج إلى حساب – فقط الشطرنج عبر الإنترنت يعمل بحساب على Lichess.",
    calm_point_4: "لا تتبّع ولا ملفات تعريف ارتباط. تبقى الألعاب المحفوظة والإحصاءات في المتصفح على جهازك.",
    calm_point_5: "مصمَّم لأجهزة القراءة بالحبر الإلكتروني: نص داكن على خلفية فاتحة، ولا تُعرض الفروق أبدًا بالرمادي أو اللون وحده.",
    calm_point_6: "لا ضغط للوقت. الاستثناءات: «إنسان، حيوان، جماد» مع مؤقت اختياري للجولة (مطفأ افتراضيًا)، وساعة «كاسحة الألغام»، ووقت التفكير في الشطرنج عبر الإنترنت على Lichess.",
    calm_point_7: "بعد الفتح الأول يعمل كل شيء دون إنترنت إذا كان المتصفح يدعم ذلك، ما عدا الشطرنج عبر الإنترنت.",
    calm_point_8: "وللأطفال أيضًا: لا يوجد في الألعاب ما يُشترى أو يُشارَك. تحتوي صفحة «حول» على رابط تبرع اختياري إلى PayPal.",
    calm_kids: "ألعاب للأطفال، معظمها يمكن لعبه دون معرفة القراءة:",
    seo_title_calm: "اللعب بهدوء – ألعاب بلا إعلانات ولا رسوم متحركة | PaperGames",
    seo_desc_calm: "PaperGames للعب بهدوء: بلا رسوم متحركة ولا أصوات ولا إعلانات ولا إشعارات ولا تتبّع، ولا حاجة إلى حساب. مصمَّم للحبر الإلكتروني ويعمل دون اتصال.",
    seo_title_games: "كل الألعاب – PaperGames",
    seo_desc_games: "تصفح كل ألعاب PaperGames المجانية الـ{games} من ألعاب لوحية وألغاز وابحث فيها ورتبها أبجديًا أو حسب النوع.",
    seo_title_guide: "دليل الإعداد | PaperGames",
    seo_desc_guide: "كيف تثبّت PaperGames على قارئك الإلكتروني أو جهازك اللوحي: افتحه في المتصفح وأضفه إلى الشاشة الرئيسية وواصل اللعب دون اتصال تمامًا.",
    seo_title_devices: "الأجهزة المجرَّبة – على أي قارئات يعمل PaperGames | PaperGames",
    seo_desc_devices: "على أي قارئات إلكترونية يعمل PaperGames بشكل مؤكد، وما الذي لم يُجرَّب بعد، وكيف تتحقق من جهازك وتبلغنا – بلا نموذج ولا حساب.",
    seo_title_impressum: "بيانات قانونية | PaperGames",
    seo_desc_impressum: "البيانات القانونية (Impressum) لـ PaperGames، وهي مجموعة مجانية من {games} لعبة لوحية دون اتصال لقارئات الحبر الإلكتروني يديرها Christopher Müller.",
    seo_title_datenschutz: "سياسة الخصوصية | PaperGames",
    seo_desc_datenschutz: "سياسة الخصوصية لـ PaperGames: بلا ملفات تعريف ارتباط ولا تحليلات ولا إعلانات. تخزين محلي فقط، مع تسجيل دخول اختياري إلى Lichess للشطرنج عبر الإنترنت.",
    seo_title_stats: "إحصاءاتك | PaperGames",
