    home_senet_desc: "من أقدم ألعاب الطاولة المعروفة، من مصر القديمة. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    game_shogi: "شوغي",
    home_shogi_desc: "الشطرنج الياباني، حيث تغيّر القطع المأسورة جانبها وتعود إلى المعركة. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    game_card_tactics: "تكتيك البطاقات",
    home_card_tactics_desc: "مبارزة سريعة وأنيقة تحسمها خمس بطاقات حركة متبدلة. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    cardtactics_neutral_card: "البطاقة التالية:",
    cardtactics_history_intro: "إضافة حديثة إلى عائلة ألعاب الاستراتيجية المجردة، مبنية حول تحوير صغير لحركة الشطرنج: فبدلًا من أن يكون لكل قطعة طريقة حركة ثابتة، تقرر مجموعة بطاقات مشتركة ما هو ممكن من دور إلى دور.",
    game_hnefatafl: "هنيفاتافل (شطرنج الفايكنغ)",
    home_hnefatafl_desc: "لعبة إسكندنافية غير متماثلة: على الملك أن يهرب، وعلى المهاجمين أن يحاصروه. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    hnefatafl_history_intro: "من أقدم عائلات ألعاب الطاولة في شمال أوروبا، لُعبت في أنحاء عالم الفايكنغ قرونًا قبل أن يصل إليه الشطرنج.",
    game_tablut: "تابلوت",
    home_tablut_desc: "أكبر ألعاب تافل وأوثقها توثيقًا: رقعة 9×9 على الملك فيها أن يصل إلى زاوية، وعلى المهاجمين أن يحاصروه أولًا.",
    tablut_history_intro: "أفضل أعضاء عائلة تافل توثيقًا على الإطلاق، بفضل دفتر ملاحظات عالم طبيعة من القرن الثامن عشر.",
    game_wall_maze: "متاهة الجدران",
    home_wall_maze_desc: "تسابق إلى الطرف الآخر من الرقعة وابنِ الجدران لتعيق خصمك. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    wallmaze_history_intro: "متاهة الجدران لعبة استراتيجية مجردة حديثة تحوّل سباقًا بسيطًا عبر شبكة إلى مبارزة تكتيكية حقيقية، بمجرد إضافة بضعة جدران.",
