    hex_history_intro: "حالة نادرة لاختراع اللعبة البسيطة الأنيقة نفسها مرتين - كلٌّ على حدة بحسب الرواية الشائعة - على يد شخصين اشتهرا لاحقًا لأسباب مختلفة تمامًا.",
    game_halma: "هالما",
    home_halma_desc: "سابق بكل قطعك عبر الرقعة إلى معسكر خصمك. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    halma_history_intro: "إعادة صياغة أمريكية للعبة إنجليزية أقدم، ظلت شائعة أكثر من قرن كسباق بسيط سهل التعلم لكنه يكافئ التخطيط الدقيق.",
    game_sternhalma: "الداما الصينية",
    home_sternhalma_desc: "سابق بكل كراتك العشر عبر الرقعة النجمية إلى الرأس المقابل لك. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    sternhalma_history_intro: "سليلة للعبة هالما الأقدم على رقعة نجمية، سُوّقت باسم غريب لا علاقة له بمكان اختراعها الفعلي.",
    game_dotsandboxes: "النقاط والمربعات",
    home_dotsandboxes_desc: "ارسم خطوطًا بين النقاط لإكمال المربعات والاستحواذ عليها - من يكمل مربعًا يلعب مرة أخرى. على لوحة من 4 × 4 أو 5 × 5 أو 6 × 6 أو 8 × 8 مربعات، لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
