    dotsandboxes_legend_p2: "اللاعب 2: خطوط منقَّطة، والمربعات معلَّمة بدائرة",
    dotsandboxes_history_intro: "لعبة بالورقة والقلم عمرها أكثر من قرن، وموضوع دراسة رياضية جادة حقًا.",
    game_fanorona: "فانورونا",
    home_fanorona_desc: "لعبة مدغشقر الوطنية: حرّك القطع على شبكة خطوط 5×9 لتأسر بالاقتراب أو بالانسحاب. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    game_konane: "كونانه",
    home_konane_desc: "الداما الهاوايية: رقعة ممتلئة بأحجار متناوبة وسلاسل قفز مستقيمة، تبدأ بطقس فريد لإزالة حجرين. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    fanorona_history_intro: "لعبة الطاولة الوطنية في مدغشقر، ومصدر فخر ثقافي حقيقي وأساطير.",
    fanorona_choose_capture_type: "يمكنك الأسر إلى الأمام أو إلى الخلف - اختر واحدًا:",
