    fanorona_done_capturing_btn: "أنهيت الأسر",
    game_ludo: "لودو",
    home_ludo_desc: "لعبة السباق الكلاسيكية على شكل صليب، المنحدرة من لعبة باتشيسي القديمة. العب بلون واحد ضد خصوم حاسوبيين، أو مرّروا الجهاز بينكم: من 2 إلى 4 لاعبين على اللوحة الكلاسيكية، وحتى 6 على اللوحة ذات الأذرع الستة.",
    ludo_mode_hotseat: "لاعبان على جهاز واحد",
