    ludo_roll_die: "ارمِ",
    ludo_history_intro: "سليلة حديثة تُنتج بكميات كبيرة لإحدى أقدم ألعاب الطاولة في الهند.",
    konane_history_intro: "لعبة هاوايية أصيلة تقليدية للأحجار والاستراتيجية، نُقشت مباشرة في الأرض التي لُعبت عليها.",
    konane_continue_jumping: "يمكنك مواصلة القفز بهذا الحجر، أو التوقف هنا.",
    konane_done_jumping_btn: "أنهيت القفز",
    game_surakarta: "سوراكارتا",
    home_surakarta_desc: "لعبة الأسر الإندونيسية ذات المسارات الدائرية: الخطوات العادية لا تأسر أبدًا، وحده الانزلاق عبر أحد مسارات الزوايا الأربعة يأسر. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    surakarta_history_intro: "لعبة طاولة إندونيسية تقليدية سُمّيت باسم المدينة نفسها في جاوة التي يُعتقد أنها نشأت فيها.",
    game_marblepush: "دفع الكرات",
    home_marblepush_desc: "ادفع 6 من كرات خصمك خارج الرقعة السداسية لتفوز. لاعبان على جهاز واحد أو ضد الحاسوب، مع كل قواعد الدفع والتحريك الجانبي للصفوف.",
    marblepush_history_intro: "لعبة دفع لشخصين على رقعة سداسية، لا سبيل فيها للأسر إلا بدفع كرات الخصم خارج الحافة.",
    marblepush_selection_hint: "اضغط على خانة مميزة لتحريك هذا التحديد، أو امسحه أدناه.",
    marblepush_clear_selection_btn: "امسح التحديد",
    game_baghchal: "باغ تشال",
    home_baghchal_desc: "لعبة الصيد التقليدية في نيبال: 4 نمور ضد 20 ماعزًا على رقعة خطوط 5×5 على طراز القِرق. لاعبان على الجهاز نفسه أو ضد المحرك المدمج، بأي من الجانبين.",
    baghchal_history_intro: "أشهر ألعاب الطاولة التقليدية في نيبال: نمور تطارد الماعز عبر شبكة من الخطوط، بجذور أقدم بكثير من أي تدوين مكتوب للقواعد.",
    game_amazons: "الأمازونات",
    home_amazons_desc: "حرّك أمازونًا تتحرك كالوزير، ثم أطلق سهمًا دائمًا من خانتها الجديدة لتسدّ الرقعة شيئًا فشيئًا. لاعبان على الجهاز نفسه أو ضد المحرك المدمج.",
    amazons_history_intro: "لعبة الأمازونات لعبة استراتيجية مجردة حديثة تدور حول تقسيم المساحة بإغلاق الرقعة بشكل دائم، خانة بعد خانة.",
    game_sudoku: "سودوكو",
    home_sudoku_desc: "املأ شبكة 9×9 بالأرقام بحيث يحتوي كل صف وعمود ومربع 3×3 على الأرقام 1-9 مرة واحدة فقط. لغز جديد بحل وحيد، بثلاثة مستويات صعوبة.",
    game_peg_solitaire: "سوليتير الأوتاد",
    home_peg_solitaire_desc: "اقفز بالأوتاد فوق بعضها حتى لا يبقى إلا وتد واحد – على الصليب الإنجليزي أو على واحدة من رقع أخرى عدة، من المربع 6×6 إلى صليب فيغليب ذي الـ45 حفرة.",
    game_minesweeper: "كاسحة الألغام",
    home_minesweeper_desc: "اكشف كل خانة آمنة مستعينًا بالأرقام، دون أن تفجّر لغمًا مخفيًا.",
    game_nonograms: "النونوغرام",
    home_nonograms_desc: "استخدم أرقام الصفوف والأعمدة لكشف صورة مخفية، خانةً بعد خانة. لغز جديد بحل وحيد، بثلاثة أحجام.",
    game_2048: "2048",
    home_2048_desc: "حرّك البلاطات المرقمة وادمجها لتصل إلى 2048 قبل أن تمتلئ الرقعة. واصل اللعب بعدها لترفع أفضل نتيجة لك.",
    game_mahjong_solitaire: "ماهجونغ سوليتير",
    home_mahjong_solitaire_desc: "أفرغ ترتيب البلاطات المكدسة بمطابقة الأزواج المتماثلة. كل توزيع مولَّد بحيث يكون له حل دائمًا.",
    game_freecell: "FreeCell",
    home_freecell_desc: "لعبة الورق الفردية الكلاسيكية التي يمكن الفوز في كل توزيعة تقريبًا بالنقلات الصحيحة. مع النقلات الجماعية الكاملة وجمع الأوراق إلى الأسس بنقرة واحدة.",
