    game_blockers: "سد الطريق",
    home_blockers_desc: "سباق نرد نحو الهدف في أعلى اللوحة للاعبين من 2 إلى 6: الكتل تسد الطرق، ومن يتوقف على كتلة يضعها في طريق الآخرين. ضد الحاسوب أو مع الأصدقاء على جهاز واحد.",
    bl_level_label: "المستوى",
    bl_board_aria: "لوحة سد الطريق",
    bl_history_intro: "سد الطريق لعبة سباق في PaperGames، تستعير عناصر قديمة من ألعاب السباق بالنرد مثل إعادة القطع إلى البيت وسد الطريق.",
    quickrules_blockers_1: "ارمِ النرد وحرّك قطعة واحدة بعدد الخانات نفسه تمامًا على الطرق نحو الهدف في الأعلى.",
    quickrules_blockers_2: "لا يمكن لأي قطعة أن تتجاوز كتلة. إذا توقفت على كتلة، تضعها على خانة فارغة أخرى – في طريق شخص آخر. قبل اللعب تختار عدد الكتل: قليلة أو عادية أو كثيرة.",
    quickrules_blockers_3: "في النصف العلوي (الخانات المستديرة) إذا توقفت على قطعة لاعب آخر تعود إلى بيتها؛ وعلى الخانات المربعة في الأسفل تكون القطع آمنة. أول قطعة تصل إلى الهدف تفوز، أو، إن اختير ذلك قبل اللعبة، أول لاعب تصل كل قطعه إلى الهدف.",
    quickrules_blockers_4: "لوحة «سريعة» (تُختار قبل اللعب): أصغر، ولكل لاعب 4 قطع؛ القطعة على خانة الاستراحة (مثمّن) آمنة، ولا تتسع إلا لقطعة واحدة، ولا يوضع عليها كتلة.",
