    game_skat: "Skat",
    home_skat_desc: "لعبة الورق الألمانية الكلاسيكية لثلاثة لاعبين: أنت ضد حاسوبين، مع المزايدة والسكات ولعب اليد والغراند والنول، وتُحسب قيمة اللعبة وفق القواعد الرسمية. أوراق فرنسية أو ألمانية؛ وقائمة نقاط لعدة ألعاب.",
