    sk_history_intro: "نشأت لعبة سكات نحو 1810–1813 في ألتنبورغ في تورينغن؛ وفيها مقر الاتحاد الألماني لسكات الذي تأسس عام 1899.",
    quickrules_skat_1: "زايد بالقيم الموجودة على الأزرار؛ من يزايد بأعلى قيمة يصبح اللاعب المنفرد ويلعب وحده ضد الآخرَين.",
    quickrules_skat_2: "يأخذ اللاعب المنفرد السكات ويضع ورقتين جانبًا، أو يلعب يد، ثم يختار اللعبة: لونًا أو غراند أو نول.",
