    game_schafkopf: "Schafkopf",
    home_schafkopf_desc: "لعبة الورق البافارية لأربعة لاعبين بالأوراق الألمانية: أنت ضد ثلاثة حواسيب في «زاوشبيل» و«فينتس» و«سولو»، مع شنايدر وشفارتس والأوراق المتتالية وقائمة نقاط. نقاط فقط.",
    sf_history_intro: "ذُكرت لعبة شافكوبف لأول مرة عام 1782 في ساكسونيا؛ وأول لعبة بافارية بوضوح موثقة عام 1849.",
    quickrules_schafkopf_1: "مرّر أو أعلن لعبة: زاوشبيل (تستدعي آسًا، ومن يملكه شريكك)، أو فينتس، أو سولو.",
    quickrules_schafkopf_2: "الأوبر والأونتر أوراق رابحة عالية (وفي فينتس الأونتر فقط)؛ اتبع اللون. ويجب لعب الآس المستدعى عندما يُلعب لونه.",
    quickrules_schafkopf_3: "يحتاج طرف اللاعب إلى 61 من 120 نقطة. شنايدر وشفارتس والأوراق المتتالية ترفع النتيجة.",
