    game_canasta: "Canasta",
    home_canasta_desc: "لعبة الرامي الكلاسيكية لشخصين بـ108 أوراق: مجموعات من رتبة واحدة، وكاناستا من سبع أوراق، والجوكر والاثنان أوراق حرة، والثلاثة الحمراء والسوداء. أنت ضد الحاسوب، حتى 5000 نقطة أو لعبة قصيرة حتى 2000.",
    cn_history_intro: "نشأت الكاناستا في مونتيفيديو بالأوروغواي؛ ويُؤرَّخ ظهورها عادةً بعام 1939، وإن ذكرت بعض المصادر عامًا لاحقًا. ووصلت إلى نيويورك عام 1949.",
    quickrules_canasta_1: "اسحب ورقتين من الكومة أو خذ كومة المهملات كلها؛ ويجب أن تدخل ورقتها العليا فورًا في مجموعة.",
    quickrules_canasta_2: "أنزل ثلاث أوراق على الأقل من رتبة واحدة؛ الجوكر والاثنان أوراق حرة. سبع أوراق تصنع كاناستا.",
    quickrules_canasta_3: "بكاناستين يمكنك الإنهاء. الثلاثة الحمراء تمنح نقاطًا إضافية؛ اللعب حتى 5000 نقطة (القصيرة: 2000).",
