    msg_cn_r_keep: "لا يمكنك الإنهاء بعد (تلزم كاناستان): أبقِ ورقة واحدة على الأقل للتخلّص منها.",
    msg_cn_last_card: "أضف ورقتك الأخيرة إلى مجموعة لتنهي.",
    game_bridge: "Bridge",
    home_bridge_desc: "البريدج التعاقدي لأربعة لاعبين: أنت وشريكك الحاسوب ضد حاسوبين. مزايدة موجَّهة بالأزرار، واليد المكشوفة (الدمية) على الطاولة، والعدّ بطريقة شيكاغو (أربع توزيعات) أو الرَّبَر.",
    br_history_intro: "يعود البريدج إلى الويست؛ وأول قواعد معروفة («Biritch, or Russian Whist») تعود إلى 1886، والبريدج التعاقدي إلى 1925.",
    quickrules_bridge_1: "زايد على عدد الأكلات فوق ست التي سيأخذها فريقك، بلون رابح أو بلا لون رابح؛ وأعلى مزايدة تصبح العقد.",
    quickrules_bridge_2: "يلعب المعلن باليدين: الدمية (شريكه) مكشوفة. اتبع اللون؛ أعلى ورقة رابحة تفوز.",
    quickrules_bridge_3: "أنجز العقد لتكسب النقاط؛ وإن نقصت الأكلات كسبها الخصمان. شيكاغو: أربع توزيعات.",
