    home_tenpairs_desc: "لغز الورقة والقلم لشطب الأرقام: أزواج متساوية أو مجموعها 10 ويرى أحدها الآخر. إن علقت فأضف الأرقام الباقية. بداية كلاسيكية أو عشوائية بثلاثة مستويات.",
