    home_mathcross_desc: "ضع الأعداد من 1 إلى 9 كلًّا مرة واحدة بحيث يصح كل صف وكل عمود - والحساب من اليسار إلى اليمين. ثلاثة مستويات، دائمًا حل واحد فقط، دون تخمين.",
    mc_history_intro: "لغز عددي من عمليات في الصفوف والأعمدة، قريب من المربع السحري القديم المكوّن من الأعداد من 1 إلى 9.",
