    home_villains_desc: "يلعب كل لاعب دور شرير من حكايات الأخوين غريم له هدفه الخاص – الساحرة والذئب ورامبلستيلتسكين وغيرهم – بينما يظهر الأبطال من الكومة ويعرقلون طريقه. من 2 إلى 4 لاعبين، ضد الحاسوب أو على جهاز واحد.",
    quickrules_villains_1: "أكمل خطة شريرك: لكل خطوة مكان وتكلفة تُدفع بأوراق السحر؛ ورقة إشارة المكان تُحسب بقيمتها، وكل ورقة أخرى تُحسب 1.",
    quickrules_villains_2: "في كل دور فعلان: خذ ورقتين من السوق أو الكومة، أو نفّذ خطوة. الأبطال مخفيون في الكومة: عندما يظهر بطل، يدخل فورًا إلى مملكتك في المكان الذي تحمل إشارته.",
    quickrules_villains_3: "يرفع البطل تكلفة الخطوات في مكانه حتى تُنفذ فيه خطوة. عندما يكمل أحدهم الخطة، تستمر الجولة حتى نهايتها؛ ويفوز من بقيت لديه أكبر قيمة في يده.",
