    home_forestvillage_desc: "تجمع حيوانات الغابة الطين والبذور والريش، وترسل العمال لبناء قريتها. يخفض الحيوان المطابق تكلفة مبناه بريشة واحدة. من لاعب إلى أربعة، منفردًا أو ضد الحاسوب.",
    quickrules_forestvillage_1: "اجمع أكبر عدد من النقاط من البطاقات والأقاليم والمهمة. يلعب الجميع عامًا واحدًا معًا؛ وتنتهي اللعبة بعد الشتاء.",
    quickrules_forestvillage_2: "في دورك، أرسل سنجابًا واحدًا ثم ابنِ بطاقة واحدة كحد أقصى. يحصل أول سنجاب في المكان على المكافأة. كل 4 بطاقات في قريتك تمنحك سنجابًا إضافيًا.",
    quickrules_forestvillage_3: "تظهر 6 بطاقات في الفسحة المشمسة. يكلف الحيوان ريشة واحدة أقل بجوار مبنى من موطنه. تشكل 3 بطاقات من الموطن نفسه إقليمًا.",
