    ab_item_goldenseed: "البذرة الذهبية",
    ab_room_cave_1: "تتساقط قطرات الماء من السقف في بركة صغيرة صافية.",
    ab_room_cave_2: "تنمو بلّورات زرقاء من الجدران وتتوهج بلطف.",
    ab_room_cave_3: "ممر ضيق. عليك أن تنحني تحت صخرة منخفضة.",
    ab_room_cave_4: "عربات منجم قديمة تقف على قضبان صدئة. عمل أحدهم هنا منذ زمن بعيد.",
    ab_room_cave_5: "ينفتح الكهف على قاعة عالية. يتردد صدى خطواتك.",
    ab_room_cave_6: "رمل لامع يغطي الأرض ويطقطق تحت حذائك.",
    ab_room_cave_7: "تهب ريح باردة من شق في الصخر.",
    ab_room_cave_8: "ينمو هنا فطر بحجم الكراسي، رائحته رائحة التراب.",
    ab_room_cave_9: "جدول تحت الأرض يندفع في مجرى حجري.",
    ab_room_cave_10: "رسوم غريبة لنجوم تغطي أحد الجدران.",
    ab_room_cave_11: "تتدلى الهوابط من السقف كأنها جليد من حجر.",
    ab_room_cave_12: "كهف جانبي صغير. ترك أحدهم هنا بطانية قديمة.",
    ab_room_cave_13: "يصعد الدرب فوق صخور ملساء يجعلها الطحلب زلقة.",
    ab_room_cave_14: "خفافيش نائمة في زاوية مظلمة. تمشي على أطراف أصابعك.",
    ab_room_cave_15: "حجرة مستديرة أرضها ملساء كأنها مصقولة.",
    ab_room_cave_16: "طحلب أخضر يضيء الجدران بوهج شاحب.",
    ab_room_cave_17: "كان هنا جسر من الحبال يومًا ما. لم يبقَ إلا الأعمدة.",
    ab_room_cave_18: "الهواء هنا دافئ. في مكان ما في الأعماق شيء يهدر.",
    ab_room_cave_19: "شظايا البلّور في كل مكان، كأن حجرًا كبيرًا انفجر.",
    ab_room_cave_20: "ركن هادئ. يلقي مصباحك ظلالًا طويلة.",
    ab_room_tower_1: "رفوف مليئة بكتب مغبرة تصل إلى السقف.",
    ab_room_tower_2: "درج حلزوني يلتف صعودًا. الدرجات تصرّ.",
    ab_room_tower_3: "غربان تجلس على عارضة وتنظر إليك بعيون لامعة.",
    ab_room_tower_4: "مطبخ قديم. قدر معلّق فوق موقد بارد.",
    ab_room_tower_5: "من نافذة مستديرة ترى الغابة بعيدًا في الأسفل.",
    ab_room_tower_6: "غرفة دراسة بمكتب ضخم. جفّ الحبر في المحابر.",
    ab_room_tower_7: "خلف جدار زجاجي تدور تروس ببطء. تك، تك.",
    ab_room_tower_8: "ممر طويل فيه صور. تبدو عيونها كأنها تتبعك.",
    ab_room_tower_9: "غرفة مليئة بالخرائط. إحداها تُظهر برجًا مثل هذا.",
    ab_room_tower_10: "شموع تشتعل على طاولة مع أنه لا يبدو أن أحدًا هنا.",
    ab_room_tower_11: "مخزن فيه جِرار من الأعشاب المجففة والمساحيق الملونة.",
    ab_room_tower_12: "تصفر الريح عبر مصراع مكسور.",
    ab_room_tower_13: "غرفة موسيقى. قيثارة تعزف نغمة وحدها.",
    ab_room_tower_14: "جسر ضيق من الألواح يمتد من جدار إلى آخر.",
    ab_room_tower_15: "غرفة نوم فيها سرير بمظلة. الستائر مليئة بالثقوب.",
    ab_room_tower_16: "ورشة فيها مقراب موجّه نحو السماء.",
    ab_room_tower_17: "ريش أسود منتشر على الأرض كلها.",
    ab_room_tower_18: "مرآة معلقة على الجدار، لكنها تُظهر غرفة أخرى.",
    ab_room_tower_19: "شرفة صغيرة. هنا في الأعلى رائحة الريح رائحة المطر.",
    ab_room_tower_20: "قاعة باردة أرضها من بلاط أسود وأبيض.",
    ab_room_forest_1: "يتعلق الضباب بين الأشجار. بالكاد ترى يدك.",
    ab_room_forest_2: "فسحة مليئة بالأزهار. النحل يطنّ في الشمس.",
    ab_room_forest_3: "درب قديم غطّته السراخس.",
    ab_room_forest_4: "شجرة مجوفة كبيرة بما يكفي لتقف داخلها.",
    ab_room_forest_5: "بركة صغيرة. تقفز الضفادع في الماء حين تقترب.",
    ab_room_forest_6: "جذور بسماكة الذراع تعترض الطريق.",
    ab_room_forest_7: "تغرد الطيور عاليًا في رؤوس الأشجار.",
    ab_room_forest_8: "دائرة من الحجارة البيضاء في العشب.",
    ab_room_forest_9: "شجيرات العليق تنمو على طول جدار حجري.",
    ab_room_forest_10: "الأرض لينة خضراء من الطحلب. المكان هادئ جدًا.",
    ab_room_forest_11: "جذع ساقط يعبر وهدة كأنه جسر.",
    ab_room_forest_12: "كوخ مهجور. بابه مفتوح.",
    ab_room_forest_13: "تصرّ أشجار الصنوبر العالية في الريح.",
    ab_room_forest_14: "أضواء صغيرة ترقص فوق مستنقع.",
    ab_room_forest_15: "شجرة بلوط ضخمة نُحت وجه في لحائها.",
    ab_room_forest_16: "ينمو الفطر في دائرة كاملة.",
    ab_room_forest_17: "جدول يخرخر فوق حصى أملس.",
    ab_room_forest_18: "أجمة مظلمة. الأغصان تخدش أكمامك.",
    ab_room_forest_19: "تلة مشمسة. من هنا يبدو الضباب في الأسفل كالبحر.",
    ab_room_forest_20: "درجات حجرية قديمة تمر بين شجرتي بتولا.",
    home_adventurebook_desc: "لعبة أدوار لشخص واحد: أنشئ بطلًا، واستكشف غرفة بعد غرفة كهفًا أو برجًا أو غابة، وارمِ النرد في الاختبارات والقتال، وأعِد كنزًا مفقودًا. سهل أو متوسط أو صعب.",
