    msg_t_mc_filled: "المملوء: {n} من {m} مربعات",
    game_differences: "اكتشف الفروق",
    home_differences_desc: "صورتان تختلفان في 3 أو 5 أو 7 مواضع: شيء ناقص، أو بنقش آخر، أو معكوس، أو مُزاح. اضغط فرقًا في أي من الصورتين. بلا ضغط وقت، ومع تلميح إن علقت. أو ابحث في الصورة: جد من 5 إلى 10 أشياء في صورة كبيرة لغرفة - المطبخ أو العلّية أو الحديقة وتسع غرف أخرى.",
    df_history_intro: "لغز معروف من الصحف ومجلات الأطفال وكتب الألغاز؛ ومتى وأين ظهر أول مرة غير موثق توثيقًا موثوقًا.",
    quickrules_differences_1: "تختلف الصورتان في بضعة مواضع - 3 أو 5 أو 7 حسب المستوى.",
    quickrules_differences_2: "اضغط فرقًا في أي من الصورتين: يُحاط بدائرة في كلتيهما. قد يكون شيء ناقصًا، أو بنقش آخر، أو معكوسًا، أو مُزاحًا.",
    quickrules_differences_3: "لا يوجد حد زمني ولا عقوبة على الضغط الخاطئ. هل علقت؟ زر التلميح يؤطر منطقة فيها فرق.",
    quickrules_differences_search_1: "تظهر الأشياء التي عليك العثور عليها فوق صورة الغرفة. اضغط كلّ واحد منها في الصورة.",
