    game_pentomino: "لغز الخماسيات",
    home_pentomino_desc: "ضع القطع الاثنتي عشرة المكوّنة من خمسة مربعات في مستطيل - التدوير والقلب بضغطة، دون سحب. وضع حر في أربعة مقاسات، أو مع قطع بداية معطاة وحل واحد بالضبط.",
    pt_history_intro: "اثنتا عشرة قطعة من خمسة مربعات لكل منها: لغز نشره هنري دودني عام 1907، وسمّاها سولومون غولومب «خماسيات» (pentominoes) عام 1953.",
    quickrules_pentomino_1: "املأ المستطيل بالقطع؛ يُغطى كل مربع مرة واحدة بالضبط.",
    quickrules_pentomino_2: "اختر قطعة أسفل اللوحة، ودوّرها أو اقلبها، ثم اضغط المربع الذي يجب أن تقع عليه نقطتها. اضغط قطعة موضوعة لتأخذها من جديد.",
    quickrules_pentomino_3: "في «قطع بداية معطاة» تكون بعض القطع ثابتة، ولا تناسب البقية إلا بطريقة واحدة.",
