    msg_t_pt_info: "الموضوعة: {n} من {m} قطع",
    game_glidelanes: "الطريق الحر",
    home_glidelanes_desc: "اضغط سهمًا فينزلق خارج اللوحة - إن لم يعترض طريقه سهم آخر. أفرغ اللوحة كلها؛ لكل لغز حل، مع التراجع والتلميحات ودون حد للوقت. في الصعب والخبير تنزلق الأسهم المسدودة إلى الأمام وقد تعلق.",
    aw_history_intro: "القطع التي لا تنزلق إلا في اتجاه واحد من أقارب ألغاز الانزلاق التي صارت هوسًا عام 1880؛ أما نسخة الأسهم فلغز حديث.",
    quickrules_glidelanes_1: "اضغط سهمًا: يغادر اللوحة في اتجاهه إن كان الطريق حتى الحافة خاليًا.",
    quickrules_glidelanes_2: "إن اعترض طريقَه سهم آخر فلا يحدث شيء - أخرج ذلك السهم أولًا. في الصعب والخبير ينزلق بدلًا من ذلك حتى ذلك السهم.",
    quickrules_glidelanes_3: "أفرغ اللوحة كلها. لكل لغز حل؛ و«تلميح» يعلِّم سهمًا يستطيع الخروج.",
    aw_win_title: "أُفرغت اللوحة!",
