    msg_aw_start: "اضغط سهمًا لترسله خارج اللوحة.",
    tg_level_outline: "المحيط فقط",
    game_loosen: "فكّ الحلقات",
    home_loosen_desc: "حلقات متشابكة، لكل منها فتحة: أدِرها - والحلقات المتشابكة معها تدور في الاتجاه المعاكس - حتى تنفك واحدة بعد الأخرى. ثلاثة مستويات، مع أقل عدد من الحركات والتراجع والتلميحات.",
    lr_history_intro: "ألغاز الحلقات قديمة - فقد وُصفت الحلقات الصينية نحو عام 1500؛ أما هذه الصيغة المسطحة ذات الفتحات فجديدة.",
    quickrules_loosen_1: "اضغط على حلقة: تدور ربع دورة باتجاه عقارب الساعة، وتدور الحلقات المتشابكة معها في الاتجاه المعاكس.",
    quickrules_loosen_2: "تكون الحلقة حرة عندما تقع فتحتها حيث تكون الحلقة المتشابكة فوقها - اضغط عليها فتخرج.",
    quickrules_loosen_3: "أخرج كل الحلقات؛ الحلقات التي في الأطراف أولًا. «تلميح» يُظهر حركة.",
    lr_win_title: "انفكّت كلها!",
