    dg_dice_none: "لم يُرمَ بعد",
    dg_roll: "ارمِ النرد",
    game_weidefreunde: "أصدقاء المرعى",
    home_weidefreunde_desc: "لعبة ورق ونرد للأطفال: ارمِ نرد الحيوانات واجمع حيوانات المزرعة الخمسة – البقرة والخروف والخنزير والدجاجة والحصان – في مرعاك الخاص. صور فقط، لا حاجة للقراءة، بلا حدّ زمني. ضد الحاسوب أو مع حتى أربعة لاعبين على جهاز واحد.",
    weidefreunde_history_intro: "الألعاب التي تستخدم الصور بدل الأرقام والبطاقات التي تُجمع من أولى ألعاب الأطفال الصغار، وهذه اللعبة تجمع بين الاثنتين.",
    quickrules_weidefreunde_1: "ارمِ النرد. يُظهر حيوانًا أو المزارع.",
    quickrules_weidefreunde_2: "إذا كانت بطاقة ذلك الحيوان في الساحة وليس عندك في المرعى، تنتقل البطاقة إليك. مع المزارع تأخذ أي بطاقة تنقصك. وإلا فأعد بطاقة واحدة من الساحة.",
    quickrules_weidefreunde_3: "يفوز من يجمع أولًا الحيوانات الخمسة في مرعاه.",
