    wf_full_pasture: "امتلأ أحد المراعي: الحيوانات الخمسة كلها موجودة.",
    wf_howto_title: "كيف تعمل اللعبة",
    wf_howto_1: "ارمِ النرد. يُظهر حيوانًا أو المزارع.",
    wf_howto_2: "تنتقل بطاقة ذلك الحيوان من الباحة إلى مرعاك، إذا لم يكن عندك بعد.",
    wf_howto_3: "المزارع: خذ أي بطاقة من الباحة ينقصك. لا بطاقة لك: أعد بطاقة واحدة من الباحة.",
    wf_howto_4: "الهدف: الحيوانات الخمسة كلها على مرعاك. من يجمعها أولًا يفوز.",
    wf_howto_show: "كيف تعمل؟",
