    howto_title: "كيف تعمل اللعبة",
    howto_show: "كيف تعمل؟",
    howto_hide: "إخفاء الشرح",
    game_zoowurf: "رمية حديقة الحيوان",
    home_zoowurf_desc: "لعبة نرد للأطفال: ارمِ نرد الحيوانات واملأ البطاقة بالحيوانات المرسومة عليها – الأسد والفيل والزرافة والقرد والبطريق. صور فقط، دون قراءة ودون حدّ زمني. ضد الحاسوب أو حتى أربعة لاعبين على جهاز واحد.",
    zoowurf_history_intro: "رمي النرد ومطابقة الصور من أولى ألعاب الأطفال الصغار؛ وتجمع هذه اللعبة بين الاثنين مع حيوانات حديقة الحيوان.",
    quickrules_zoowurf_1: "لدى كل لاعب بطاقة خاصة به. تُظهر الحيوانات التي عليك إخراجها بالنرد.",
    quickrules_zoowurf_2: "ارمِ مرة واحدة في كل دور. تبقى على البطاقة أحجار النرد التي تُظهر حيوانًا منها أو الكفّ.",
    quickrules_zoowurf_3: "تمنح البطاقة المكتملة نقطة عن كل حيوان؛ ثم خذ بطاقة مكشوفة. عندما يصل أحدهم إلى 12 نقطة، تُلعب الجولة حتى نهايتها. يفوز من لديه أكبر عدد من النقاط.",
    game_pfotenwurf: "رمية المخلب",
    home_pfotenwurf_desc: "لعبة نرد للأطفال بنرد عليه حيوانات: ارمِ حتى ثلاث مرات، واحتفظ بالحيوانات التي تريدها واملأ ورقتك – أسود، أفيال، اثنان أو أكثر متشابهة، كلها مختلفة. أثر المخلب ورقة رابحة. صور فقط، بلا حساب. وحدك أو ضد الحاسوب أو حتى أربعة لاعبين على جهاز واحد.",
    pfotenwurf_history_intro: "رمي خمسة أحجار نرد حتى ثلاث مرات ثم اختيار مكان التسجيل فكرة قديمة في ألعاب النرد – وهنا بحيوانات بدل الأرقام.",
    quickrules_pfotenwurf_1: "ارمِ أحجار النرد الخمسة. المس الأحجار التي تريد الاحتفاظ بها وأعد رمي الباقي – حتى ثلاث مرات.",
    quickrules_pfotenwurf_2: "ثم المس خانة فارغة في ورقتك. أثر المخلب يُحسب أي حيوان. الخانة التي لا تناسب تأخذ 0 نقاط.",
    quickrules_pfotenwurf_3: "عندما تمتلئ كل الخانات تنتهي اللعبة. يفوز صاحب أكثر النقاط.",
