    home_slidepuzzle_desc: "حرّك المربعات المرقّمة حتى تصبح بالترتيب والفراغ في الأسفل يمينًا. لكل لغز حل؛ 3 × 3 أو 4 × 4 أو 5 × 5، مع تلميحات وبلا ساعة.",
    slidepuzzle_history_intro: "صندوق فيه مربعات مرقّمة ومكان واحد فارغ: في عام 1880 صار لغز الانزلاق موجة كبيرة في الولايات المتحدة.",
