    home_hanoi_desc: "انقل برج الأقراص كله إلى العمود الأيمن، قرصًا واحدًا في كل مرة، ولا تضع قرصًا كبيرًا فوق صغير أبدًا. من 3 إلى 8 أقراص، مع عدّاد للحركات وتراجع وتلميحات.",
