    home_nim_desc: "خذوا بالتناوب حجارة من الأكوام – من يأخذ الحجر الأخير يفوز (أو في قاعدة «ميزير» يخسر). ضد الحاسوب بثلاثة مستويات أو بين لاعبين.",
