    zw_goal_line: "الهدف: كل حيوان على بطاقة مكتملة يساوي نقطة. عندما يصل أحدهم إلى 12 نقطة، تُلعب الجولة حتى نهايتها. يفوز من لديه أكبر عدد من النقاط.",
    zw_level_label: "الكمبيوتر:",
    zw_level_normal: "عادي",
    zw_level_beginner: "مبتدئ",
    zw_howto_1: "لدى كل لاعب بطاقة خاصة به. تُظهر الحيوانات التي تحتاجها.",
    zw_howto_2: "ارمِ مرة واحدة في كل دور. تبقى على بطاقتك أحجار النرد التي تُظهر حيوانًا منها.",
    zw_howto_3: "ضع الكفّ بنفسك على حيوان فارغ تختاره.",
    zw_howto_4: "تمنح البطاقة المكتملة نقطة عن كل حيوان. ثم خذ إحدى البطاقتين المكشوفتين. بعد أدوار الحاسوب، المس التالي.",
    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "لعبة نرد تقليدية: ارمِ حجري نرد وأغلق الألواح المرقّمة التي يساوي مجموعها رميتك. عندما لا يناسب شيء، تُحسب الألواح المفتوحة ضدك؛ يفوز صاحب أقل نقاط، ومن يغلق كل الألواح يفوز فورًا. ضد الكمبيوتر أو مع ما يصل إلى أربعة لاعبين على جهاز واحد.",
    kk_history_intro: "لعبة نرد تقليدية بصف من الألواح المرقّمة، لُعبت في الحانات وعلى السفن، ولا يُعرف بدقة أين ومتى بدأت.",
    quickrules_klappenkasten_1: "ارمِ حجري النرد وأغلق لوحًا أو عدة ألواح يساوي مجموع أرقامها الرمية.",
    quickrules_klappenkasten_2: "تابع الرمي والإغلاق. حين لا يناسب شيء، فمجموع أرقام الألواح المفتوحة هو نقاطك.",
    quickrules_klappenkasten_3: "يفوز صاحب أقل نقاط؛ ومن يغلق كل الألواح يفوز فورًا. «تراجع» يلغي الإغلاق الأخير.",
    kk_goal_line: "الهدف: أغلق الأغطية التي يساوي مجموعها رميتك. قلة الأغطية المفتوحة تعني نقاطًا قليلة، وأقل النقاط تفوز.",
    kk_howto_1: "ارمِ النردين.",
    kk_howto_2: "أغلق الألواح التي يساوي مجموعها الرمية: 8 هي 3 و5.",
    kk_howto_3: "ارمِ مرة أخرى وأغلق ألواحًا أخرى ما دام بعضها مناسبًا.",
    kk_howto_4: "عندما لا يناسب شيء تنتهي دورتك. الألواح المفتوحة هي نقاطك، والأقل نقاطًا يفوز.",
