    sw_again_hint: "سداسي مزدوج! ارمِ مرة أخرى.",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "لعبة نرد ووتد تقليدية بإحدى عشرة فتحة مرقّمة من 2 إلى 12: ارمِ حجري نرد وضع وتدًا في فتحة المجموع أو في فتحتي كل حجر على حدة. تابع الرمي ما دام شيء يناسب؛ الفتحات الفارغة تُحسب ضدك ويفوز صاحب أقل نقاط. صيغ أخرى: السداسي المزدوج كجوكر، أو لوحة مشتركة يخرج منها من لا يستطيع وضع وتد.",
    sw_history_intro: "لعبة نرد تقليدية صغيرة على لوح بفتحات مرقّمة وأوتاد: بسيطة وقديمة، وما زالت تُباع كلعبة خشبية للجيب.",
    quickrules_steckwuerfeln_1: "ارمِ حجري نرد. ضع وتدًا في فتحة المجموع أو في فتحتي كل حجر (2 و4: الفتحة 6 أو الفتحتان 2 و4).",
    quickrules_steckwuerfeln_2: "تابع الرمي ووضع الأوتاد. حين لا يناسب شيء، فمجموع أرقام الفتحات الفارغة هو نقاطك.",
    quickrules_steckwuerfeln_3: "يفوز صاحب أقل نقاط. السداسي المزدوج جوكر (ارمِ مرة أخرى). «تراجع» يسحب الوتد الأخير.",
    sw_goal_line: "الهدف: ضع الأوتاد في الثقوب. الثقوب الفارغة تُحتسب نقاطًا، وأقل النقاط تفوز.",
