    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "لعبة مطاردة لاثنين إلى أربعة لاعبين بنرد واحد: العدد الذي يظهر هو عدد الخطوات بالضبط على طول أسهم لوحة على شكل نجمة. من يتوقف على خصم يأخذ منه إحدى نجومه الثلاث، والمرور فوقه لا يغيّر شيئاً. يفوز آخر لاعب تبقّت له نجوم.",
    sj_history_intro: "ألعاب المطاردة بالنرد تقليدية في ثقافات كثيرة؛ وهذه النسخة لها لوحتها الخاصة ذات الأسهم.",
    quickrules_sternjagd_1: "ارمِ النرد وتحرّك بالضبط بعدد الخطوات على طول الأسهم. المس إحدى الخانات المحاطة بحلقة.",
    quickrules_sternjagd_2: "أنهِ حركتك على خصم لتمسكه: يخسر نجمة ويعود إلى زاوية. المرور فوقه لا يغيّر شيئاً.",
    quickrules_sternjagd_3: "لكل لاعب ثلاث نجوم. يفوز آخر لاعب تبقّت له نجوم. «تراجع» يلغي حركة.",
    quickrules_sternjagd_4: "مع لاعبَين، يلعب اللاعب الثاني دورين متتاليين في المرة الأولى (يمكن إيقاف ذلك).",
