    home_teufelsieben_desc: "لعبة أوراق تعتمد على المخاطرة: اكشف الأوراق واحدة تلو الأخرى وتوقف في الوقت المناسب. تكرار الرقم يؤدي إلى الخسارة؛ وتسلسل أربعة أرقام أو أكثر يمنح نقاطًا إضافية. من لاعبين إلى 6، ضد الكمبيوتر أو على جهاز واحد.",
