    game_gipfelwurf: "رمية القمة",
    home_gipfelwurf_desc: "لعبة نرد محفوفة بالمخاطر: ارمِ ثلاثة أحجار نرد؛ يحدد اثنان السفح والثالث عدد الدرجات. واصل الصعود أو أقم مخيّمًا؛ إذا لم تناسب الرمية سفحك، يضيع صعود هذا الدور. تحميك الأكواخ، وتعيدك الشقوق الجليدية إلى الخلف. من 2 إلى 4 لاعبين، ضد الحاسوب أو على جهاز واحد.",
    quickrules_gipfelwurf_1: "ارمِ ثلاثة أحجار نرد: يحدد مجموع حجرين السفح، ويحدد الثالث عدد الدرجات (1-2: درجة، 3-4: درجتان، 5-6: ثلاث درجات). تصعد سفحًا واحدًا فقط في كل دور.",
    quickrules_gipfelwurf_2: "واصل الرمي أو أقم مخيّمًا. إذا لم تناسب الرمية سفحك، يضيع صعود هذا الدور، إلا إذا وصلت إلى الكوخ. إذا هبطت تمامًا على الشق الجليدي، فتراجع درجتين.",
    quickrules_gipfelwurf_3: "كل درجة في مخيّماتك تساوي نقطة؛ ومن يصل إلى القمة أولًا يحصل على 6 نقاط إضافية، ويحصل اللاحقون على 3. عندما يبلغ أحدهم الهدف، أكملوا الجولة ويفوز صاحب أكبر عدد من النقاط.",
    gw_history_intro: "تواصل الرمي أم تقيم مخيّمًا؟ رمية القمة لعبة نرد فيها مخاطرة صُنعت لـ PaperGames، من العائلة القديمة لألعاب النرد التي قد تكلّف فيها رمية إضافية كل شيء.",
