    home_advent_desc: "24 بابًا، وخلف كل باب لغز صغير: مفتاح الإضاءة وسودوكو مصغّرة ونونوغرام وFutoshiki وأبراج وCalcudoku. يُفتح الباب في يومه من ديسمبر بعد حل الباب السابق.",
