    quickrules_kleeberg_2: "ابنِ إلى الأعلى: تكون الخانة مفتوحة فقط إذا كانت الخانتان تحتها ممتلئتين.",
    quickrules_kleeberg_3: "ثلاثة من رموزك على خط مستقيم تفوز. إذا امتلأ الهرم ولم يكوّن أحد خطاً فالنتيجة تعادل.",
