    kq_cards_label: "البطاقات",
    game_oddone: "أيهما مختلف؟",
    home_oddone_desc: "عدة بطاقات متشابهة في أمر واحد إلا بطاقة: المس البطاقة التي لا تنتمي. رسوم من المجموعة نفسها أو أشكال تتفق في خاصية واحدة. ست جولات في كل لعبة وثلاثة مستويات وأزرار كبيرة وبلا حد زمني ومع تلميح إذا علقت.",
    oddone_history_intro: "إيجاد العنصر الذي لا ينتمي تمرين كلاسيكي في الكتب المدرسية واختبارات التفكير، وهو يدرّب على ترتيب الأشياء حسب خصائصها.",
    quickrules_oddone_1: "عدة بطاقات متشابهة في أمر واحد إلا بطاقة.",
    quickrules_oddone_2: "المس البطاقة التي لا تنتمي. البطاقة الخاطئة تُشطب، فجرّب غيرها.",
    quickrules_oddone_3: "ست جولات تكوّن لعبة. لا يوجد حد زمني، والتلميح يضع علامة على البطاقة التي لا تنتمي.",
