    game_shadowmatch: "لمن هذا الظل؟",
    home_shadowmatch_desc: "صورة وعدة ظلال سوداء: أي ظل يعود إليها؟ ست صور في كل لعبة وثلاثة مستويات، وفي الصعب تظهر الصورة نفسها مقلوبة أو معكوسة أيضًا. أزرار كبيرة وبلا حد زمني ومع تلميح إذا علقت.",
    shadowmatch_history_intro: "منذ قرون يرسم الناس الظلال ويقصّونها ويلعبون بها، ومطابقة الظل بجسمه تمرين صغير على التدقيق في النظر.",
