    home_patternrow_desc: "صف من الرموز يتبع نمطًا — أي رمز يأتي بعد ذلك؟ ستة صفوف في كل لعبة وثلاثة مستويات وأشكال بالأبيض والأسود وأزرار إجابة كبيرة. بلا حد زمني، ومع تلميح إذا علقت.",
    patternrow_history_intro: "صفوف العلامات المتكررة قديمة قدم الفخار والنسيج، وإكمالها مهمة محببة في الكتب المدرسية والاختبارات.",
