    home_catplaces_desc: "في كل صف وكل عمود وكل غرفة قطة واحدة بالضبط، ولا يجوز أن تتلامس قطتان، ولا حتى عند زاوية. ألغاز منطقية بثلاثة أحجام، لكل منها حل واحد فقط، تُحل دون تخمين.",
    kz_history_intro: "تأتي القواعد من لغز منطقي ابتُكر عام 2003 لبطولة العالم للألغاز في هولندا؛ وهنا تحل قطط نائمة محل النجوم.",
