    game_rings: "أدِر الحلقات",
    home_rings_desc: "من ثلاث إلى خمس حلقات متداخلة عليها أشكال. أدِر الحلقات حتى يُظهر كل شعاع من المركز الشكل نفسه - وفي المستوى الصعب تدير الحلقة جارتها معها. مع عرض أقل عدد من النقلات وزر للتلميح.",
    rg_history_intro: "الحلقات ذات العلامات التي تُدار بعضها مقابل بعض قديمة: وصف ليون باتيستا ألبرتي عام 1467 قرص تشفير من حلقتين دوّارتين. أما اللغز هنا فمصنوع لـ PaperGames.",
