    game_matches: "ألغاز أعواد الثقاب",
    home_matches_desc: "انقل عود ثقاب أو اثنين لتصبح عملية خاطئة صحيحة، أو ليُظهر الشكل العدد المطلوب من المربعات. 90 لغزًا في ثلاثة مستويات، كلٌّ منها تحقق منه الحاسوب؛ اضغط عودًا ثم مكانًا خاليًا - دون سحب.",
    mt_history_intro: "صارت أعواد الثقاب شيئًا يوميًا في القرن التاسع عشر، وسرعان ما صارت مادة للألغاز: في كتاب Professor Hoffmann «Puzzles Old and New» (1893) فصل كامل لألغاز أعواد الثقاب.",
