    game_tangram: "تانغرام",
    home_tangram_desc: "املأ محيطًا بالقطع السبع الكلاسيكية: مثلثات ومربع ومتوازي أضلاع. 90 محيطًا في أربعة مستويات، لكل منها حل تحقق منه الحاسوب. في «المحيط فقط» لا ترى إلا الخط الخارجي، وتبقى القطعة حيث تضغط - عليك أن تجرّب. اضغط على قطعة، أدرها، ثم اضغط على مكانها - دون سحب.",
